def reconcile(desired, actual):
    create = sorted(name for name in desired if name not in actual)
    update = sorted(name for name in desired if name in actual and desired[name] != actual[name])
    delete = sorted(name for name in actual if name not in desired)

    return {
        "create": create,
        "update": update,
        "delete": delete,
    }

def delays(attempts, base, cap):
    def is_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    if not is_int(attempts) or attempts < 1:
        raise ValueError("attempts must be an integer >= 1")

    if not is_int(base) or base < 0:
        raise ValueError("base must be an integer >= 0")

    if not is_int(cap) or cap < 0:
        raise ValueError("cap must be an integer >= 0")

    return [min(base * (2 ** i), cap) for i in range(attempts - 1)]

