def unique_latest(records):
    first_seen = []
    chosen = {}
    best_timestamp = {}

    for record in records:
        record_id = record["id"]
        timestamp = record["timestamp"]

        if record_id not in chosen:
            first_seen.append(record_id)
            chosen[record_id] = record
            best_timestamp[record_id] = timestamp
        elif timestamp >= best_timestamp[record_id]:
            chosen[record_id] = record
            best_timestamp[record_id] = timestamp

    return [chosen[record_id] for record_id in first_seen]
